using Arrow.SourceGenerator.Model;
using Arrow.SourceGenerator.Planning;

namespace Arrow.SourceGenerator.Emit;

/// <summary>
/// Writes the generated file for one target: the file header, the namespace and containing-type
/// scopes, and the companion type. Capability emitters fill the companion as they land.
/// </summary>
internal static class ArrowEmitter
{
    public const string HintSuffix = ".Arrow.g.cs";

    public static string HintName(EmissionPlan plan) =>
        SourceNames.HintName(plan.Target.HintIdentity, HintSuffix);

    public static string Emit(EmissionPlan plan)
    {
        var context = new EmissionContext(plan);
        TargetModel model = plan.Target;
        var writer = new SourceWriter();
        writer.Line("// <auto-generated/>");
        writer.Line("// Generated by Arrow.SourceGenerator. Do not edit.");
        writer.Line("#nullable enable");
        writer.Line();

        SourceWriter.Scope? ns =
            model.Namespace.Length > 0
                ? writer.Block("namespace " + SourceNames.DottedIdentifier(model.Namespace))
                : null;

        var containers = new SourceWriter.Scope[model.ContainingTypes.Count];
        for (int i = 0; i < model.ContainingTypes.Count; i++)
        {
            ContainingTypeModel outer = model.ContainingTypes[i];
            containers[i] = writer.Block(
                $"partial {Keyword(outer.Kind)} {SourceNames.Identifier(outer.Name)}"
            );
        }

        EmitCompanion(writer, context);
        writer.Line();
        TypedViewEmitter.EmitViewType(writer, context);

        for (int i = containers.Length - 1; i >= 0; i--)
        {
            containers[i].Dispose();
        }

        ns?.Dispose();
        return writer.ToString();
    }

    private static void EmitCompanion(SourceWriter writer, EmissionContext context)
    {
        TargetModel model = context.Target;
        writer.Line("/// <summary>");
        writer.Line(
            $"/// Apache Arrow mapping generated for <see cref=\"{model.FullyQualifiedName}\"/>."
        );
        writer.Line("/// </summary>");
        using (
            writer.Block(
                $"{model.Accessibility} static partial class {SourceNames.Identifier(model.CompanionName)}"
            )
        )
        {
            SchemaEmitter.Emit(writer, context);
            writer.Line();
            ToRecordBatchEmitter.Emit(writer, context);
            writer.Line();
            FromRecordBatchEmitter.Emit(writer, context);
            writer.Line();
            TypedViewEmitter.EmitFactory(writer, context);
            writer.Line();
            HelperEmitter.Emit(writer, context);
        }
    }

    private static string Keyword(TargetKind kind) =>
        kind switch
        {
            TargetKind.Struct => "struct",
            TargetKind.RecordClass => "record",
            TargetKind.RecordStruct => "record struct",
            TargetKind.Interface => "interface",
            _ => "class",
        };
}
